public class METBatchMonitoringTestJob extends RunBaseBatch implements BatchRetryable
{
    InventLocationId  inventLocationId;
    NoYes             transactionPerOrder;
    NoYes             generateError;
    Integer           sleepMs;
    Integer           maxRecords;
    Integer           runMode;

    DialogField       dlgInventLocationId;
    DialogField       dlgTransactionPerOrder;
    DialogField       dlgSleepMs;
    DialogField       dlgMaxRecords;
    DialogField       dlgGenerateError;
    DialogField       dlgRunMode;

    QueryRun       queryRun;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        inventLocationId,
        transactionPerOrder,
        sleepMs,
        maxRecords,
        generateError,
        runMode
    #endmacro

}

Method.Source:
public Object dialog()
{
    DialogRunbase       dialog = super();
    ;
    dlgInventLocationId    = dialog.addFieldValue(extendedtypestr(InventLocationId), inventLocationId);
    dlgTransactionPerOrder = dialog.addFieldValue(extendedtypestr(NoYesId), transactionPerOrder, "Transaction per order");
    dlgSleepMs             = dialog.addFieldValue(extendedtypestr(Integer), sleepMs, "Sleep between records (s)");
    dlgMaxRecords          = dialog.addFieldValue(extendedtypestr(Integer), maxRecords, "Max records to process");
    dlgGenerateError       = dialog.addFieldValue(extendedtypestr(NoYesId), generateError, "Generate error after first record");
    dlgRunMode             = dialog.addFieldValue(extendedtypestr(Integer), runMode, "Run mode (0 Normal or 1 with using)");

    return dialog;
}

public boolean getFromDialog()
{
    ;
    inventLocationId    = dlgInventLocationId.value();
    transactionPerOrder = dlgTransactionPerOrder.value();
    sleepMs             = dlgSleepMs.value();
    maxRecords          = dlgMaxRecords.value();
    generateError       = dlgGenerateError.value();
    runMode             = dlgRunMode.value();

    return super();
}

public InventLocationId parmInventLocationId(InventLocationId _inventLocationId = inventLocationId)
{
    inventLocationId = _inventLocationId;
    return inventLocationId;
}

public void initParmDefault()
{
    sleepMs    = 10;
    maxRecords = 1000;
    this.initQuery();
}

public void initQuery()
{
    Query                   query = new Query();
    QueryBuildDataSource    qbds = query.addDataSource(tablenum(CustTable));
    QueryBuildRange         qBR;
    ;
    qBR = SysQuery::findOrCreateRange(qbds, fieldnum(CustTable, RecId));
    qBR.status(RangeStatus::HIDDEN);

    queryRun = new QueryRun(query);
}

public boolean unpack(container _packedClass)
{
    Version    version = RunBase::getVersion(_packedClass);
    container  queryCon;
    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList, queryCon] = _packedClass;
            if (SysQuery::isPackedOk(queryCon))
            {
                queryRun = new QueryRun(queryCon);
            }
            else
            {
                this.initQuery();
            }
            break;
        default:
            return false;
    }
    return true;
}

public void run()
{
    if (runMode == 1)
    {
        this.run1();
    }
    else
    {
        this.run0();
    }
}

public void run0()
{
    QueryBuildDataSource    qBDS;
    METProcMetrics          procMetrics;
    CustTable               custTable;
    SalesLine               salesLine;
    int                     effectiveSleepMs    = sleepMs    > 0 ? sleepMs    : 10;
    int                     effectiveMaxRecords = maxRecords > 0 ? maxRecords : 1000;

    qBDS = queryRun.query().dataSourceTable(tableNum(CustTable));

    if (inventLocationId)
    {
        SysQuery::findOrCreateRange(qBDS, fieldnum(CustTable, InventLocation)).value(inventLocationId);
    }

    procMetrics = METProcMetrics::construct(METBatchLogOperation::METBatchMonitoringTest);

    if (effectiveMaxRecords > 0)
    {
        procMetrics.setTotalCount(effectiveMaxRecords);
    }
    else
    {
        procMetrics.setTotalCountFromQuery(queryRun);
    }

    procMetrics.beginTrace('Process started');


    if (transactionPerOrder == NoYes::No)
    {
        procMetrics.ttsBeginTrace();
    }

    while (queryRun.next())
    {
        custTable = queryRun.get(tablenum(CustTable));

        if (transactionPerOrder == NoYes::Yes)
        {
            procMetrics.ttsBeginTrace();
        }

        select count(RecId) from salesLine
            where salesLine.CustAccount == custTable.AccountNum;

        METGlobal::sleep(effectiveSleepMs);

        procMetrics.incProcessedCountWithDocument(custTable.AccountNum);
        // Or use procMetrics.incProcessedCount(); if you don't want to track document id in the log

        if (generateError == NoYes::Yes)
        {
            throw error("Test error generated after first record.");
        }

        if (transactionPerOrder == NoYes::Yes)
        {
            procMetrics.ttsCommitTrace();
        }

        if (procMetrics.getCurrentDocumentCount() >= effectiveMaxRecords)
        {
            break;
        }
    }

    if (transactionPerOrder == NoYes::No)
    {
        procMetrics.ttsCommitTrace();
    }

    procMetrics.endTrace();
}

public void run1()
{
    QueryBuildDataSource    qBDS;
    METProcMetrics          procMetrics;
    CustTable               custTable;
    SalesLine               salesLine;
    int                     effectiveSleepMs    = sleepMs    > 0 ? sleepMs    : 10;
    int                     effectiveMaxRecords = maxRecords > 0 ? maxRecords : 1000;

    qBDS = queryRun.query().dataSourceTable(tableNum(CustTable));

    if (inventLocationId)
    {
        SysQuery::findOrCreateRange(qBDS, fieldnum(CustTable, InventLocation)).value(inventLocationId);
    }

    procMetrics = METProcMetrics::construct(METBatchLogOperation::METBatchMonitoringTest);

    if (effectiveMaxRecords > 0)
    {
        procMetrics.setTotalCount(effectiveMaxRecords);
    }
    else
    {
        procMetrics.setTotalCountFromQuery(queryRun);
    }

    procMetrics.beginTrace('Process started');

    using (METProcMetricsScope procMetricsScope = METProcMetricsScope::constructWithErrorHandling(procMetrics))
    {
        if (transactionPerOrder == NoYes::No)
        {
            procMetrics.ttsBeginTrace();
        }

        while (queryRun.next())
        {
            custTable = queryRun.get(tablenum(CustTable));

            if (transactionPerOrder == NoYes::Yes)
            {
                procMetrics.ttsBeginTrace();
            }

            select count(RecId) from salesLine
                where salesLine.CustAccount == custTable.AccountNum;

            METGlobal::sleep(effectiveSleepMs);

            procMetrics.incProcessedCountWithDocument(custTable.AccountNum);

            if (generateError == NoYes::Yes)
            {
                throw error("Test error generated after first record.");
            }

            if (transactionPerOrder == NoYes::Yes)
            {
                procMetrics.ttsCommitTrace();
            }

            if (procMetrics.getCurrentDocumentCount() >= effectiveMaxRecords)
            {
                break;
            }
        }

        if (transactionPerOrder == NoYes::No)
        {
            procMetrics.ttsCommitTrace();
        }

        procMetrics.endTrace();
    }
}

public static METBatchMonitoringTestJob construct()
{
    return new METBatchMonitoringTestJob();
}

static ClassDescription description()
{
    return "Test batch monitoring";
}

public static void main(Args _args)
{
    METBatchMonitoringTestJob    runObject = METBatchMonitoringTestJob::construct();
    ;
    if (runObject.prompt())
    {
        runObject.runOperation();
    }
}

public static void testNestedProcMetricsScope()
{

    METProcMetrics procMetrics1 = METProcMetrics::construct(METBatchLogOperation::METBatchMonitoringTest);
    procMetrics1.setDescription(2, "Test1");

    using (METProcMetricsScope procMetricsScope1 = METProcMetricsScope::constructWithErrorHandling(procMetrics1))
    {
        METProcMetrics procMetrics2 = METProcMetrics::construct(METBatchLogOperation::METBatchMonitoringTest);
        procMetrics2.setDescription(2, "Test2");

        using (METProcMetricsScope procMetricsScope2 = METProcMetricsScope::constructWithErrorHandling(procMetrics2))
        {
            METProcMetrics procMetrics3 = METProcMetrics::construct(METBatchLogOperation::METBatchMonitoringTest);
            procMetrics3.setDescription(2, "Test3");

            using (METProcMetricsScope procMetricsScope3 = METProcMetricsScope::constructWithErrorHandling(procMetrics3))
            {
                METProcMetrics procMetricsCurrent = METProcMetricsScope::current();
                info(procMetricsCurrent.getDescription(2));
            }

            METProcMetrics procMetricsCurrent = METProcMetricsScope::current();
            info(procMetricsCurrent.getDescription(2));
        }

        METProcMetrics procMetricsCurrent = METProcMetricsScope::current();
        info(procMetricsCurrent.getDescription(2));
    }
}
